<script setup lang="ts">
import {operatorChart} from '~/utils/operatorChart'
const props=defineProps<{data:any;kind:'picking'|'packing';highlightOperator?:string}>()
const {t,locale}=useI18n()
const emit=defineEmits<{drilldown:[selection:{operatorId:number;name:string;day:string}]}>()
const selected=ref(props.highlightOperator||'')
watch(()=>props.highlightOperator,value=>selected.value=value||'')
const graph=computed(()=>operatorChart(props.data))
const table=ref(false)
const format=(n:number)=>n.toLocaleString(locale.value,{maximumFractionDigits:1})
const title=(p:any)=>`${t('nav.'+props.kind)} #${p.id} · ${p.operators.map((o:any)=>o.name).join(' / ')} · ${format(p.quantity)} ${t('operator-report.quantity')} · ${format(p.seconds/60)} ${t('operator-chart.minutes')}`
const color=(quantity:number)=>quantity===0?'#EDEFF3':quantity<=5?'#DAD6FF':quantity<=15?'#BFB9FE':quantity<=30?'#7855FE':'#4E1DBC'
watch([()=>props.data.start_date,()=>props.data.end_date],()=>{selected.value=props.highlightOperator||''})
</script>
<template><div class="operator-charts">
<section><header><h3>{{t('operator-chart.task-title')}} <span>{{t('operator-chart.axes')}}</span></h3><WButton size="sm" variant="text" @click="table=!table">{{t(table?'operator-chart.chart':'operator-chart.table')}}</WButton></header><slot name="phase-control"/>
<p class="help">{{t('operator-chart.help')}}</p>
<div class="legend"><label>{{t('operator-report.operator')}} <select v-model="selected"><option value="">{{t('operator-chart.everyone')}}</option><option v-for="op in graph.operators" :key="op.id" :value="String(op.id)">{{op.name}}</option></select></label><span>{{t('operator-chart.task-median')}} {{data.task_chart.median_per_hour==null?'—':format(data.task_chart.median_per_hour)}}</span></div>
<p v-if="!graph.points.length" class="empty">{{t('operator-chart.no-timed')}}</p>
<template v-else-if="!table"><div class="axis-name">{{t('operator-chart.minutes')}}</div><div class="scatter"><div class="y-labels"><span v-for="tick in graph.yTicks" :key="tick.value" :style="{top:tick.percent+'%'}">{{format(tick.value)}}</span></div><div class="plot"><i v-for="tick in graph.yTicks" :key="tick.value" class="gridline" :style="{top:tick.percent+'%'}"/><svg v-if="graph.median" class="median-line" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><line x1="0" y1="100" :x2="graph.median.x" :y2="graph.median.y"/></svg><NuxtLink v-for="p in graph.points" :key="p.id" class="point" :class="{muted:selected&&!p.operators.some((o:any)=>String(o.id)===selected)}" :style="{left:p.x+'%',top:p.y+'%'}" :to="'/'+kind+'/detail/'+p.id" :title="title(p)" :aria-label="title(p)"/><div class="x-labels"><span v-for="tick in graph.xTicks" :key="tick.value" :style="{left:tick.percent+'%'}">{{format(tick.value)}}</span></div></div></div><div class="x-name">{{t('operator-report.quantity')}}</div></template>
<div v-else class="task-table"><table><thead><tr><th>{{t('operator-chart.task')}}</th><th>{{t('operator-report.operator')}}</th><th>{{t('operator-report.quantity')}}</th><th>{{t('operator-chart.minutes')}}</th></tr></thead><tbody><tr v-for="p in graph.points" :key="p.id"><td><NuxtLink :to="'/'+kind+'/detail/'+p.id">#{{p.id}}</NuxtLink></td><td>{{p.operators.map((o:any)=>o.name).join(' / ')}}</td><td>{{format(p.quantity)}}</td><td>{{format(p.seconds/60)}}</td></tr></tbody></table></div>
<p class="help">{{t('operator-chart.coverage',{shown:graph.points.length,total:data.task_chart.total,untimed:data.task_chart.untimed})}}</p>
</section>
<section><header><h3>{{t('operator-chart.daily')}}</h3></header><p class="help">{{t('operator-chart.daily-help',{zone:data.timezone})}}</p><div v-if="data.items.length" class="heat-scroll"><div class="heat" :style="{minWidth:Math.max(300,graph.days.length*12+78)+'px'}"><span/><div class="heat-dates"><span v-for="day in graph.dayTicks" :key="day.date" :style="{left:day.percent+'%'}">{{day.date.slice(5).replace('-','/')}}</span></div><template v-for="row in data.items" :key="row.operator_id"><span class="person" :title="row.name">{{row.name}}</span><div class="cells" :style="{gridTemplateColumns:'repeat('+graph.days.length+',minmax(0,1fr))'}"><button type="button" v-for="day in graph.days" :key="day" @click="emit('drilldown',{operatorId:row.operator_id,name:row.name,day})" :style="{background:color(graph.daily[row.operator_id]?.[day]||0)}" :title="row.name+' · '+day+' · '+(graph.daily[row.operator_id]?.[day]||0)" :aria-label="row.name+' · '+day+' · '+(graph.daily[row.operator_id]?.[day]||0)"/></div></template></div></div><p v-else class="empty">{{t('operator-chart.no-daily')}}</p><div class="heat-legend"><span v-for="bin in [{q:0,l:'0'},{q:1,l:'1–5'},{q:6,l:'6–15'},{q:16,l:'16–30'},{q:31,l:'> 30'}]" :key="bin.q"><i :style="{background:color(bin.q)}"/>{{bin.l}}</span></div><p class="help">{{t('operator-chart.people-page')}}</p></section>
</div></template>
<style scoped>
.operator-charts{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:16px;margin:16px 24px 20px}section{min-width:0;background:var(--w-surface);border:1px solid var(--w-border);border-radius:10px;padding:16px 24px 20px;display:flex;flex-direction:column;gap:12px}header{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}h3{margin:0;font-size:16px;line-height:24px;font-weight:600}h3 span{font-size:13px;font-weight:400;color:var(--w-text-2)}.help{margin:0;color:var(--w-text-3);font-size:12px;line-height:18px}.legend{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:12px;line-height:18px;color:var(--w-text-2)}select{font:inherit;border:1px solid var(--w-border);border-radius:6px;background:white;max-width:150px;padding:3px 6px}.axis-name{margin-left:42px;font-size:12px;line-height:18px;color:var(--w-text-2)}.scatter{display:grid;grid-template-columns:34px minmax(0,1fr);gap:8px;padding-right:8px}.y-labels,.plot{position:relative;height:220px}.y-labels span{position:absolute;right:0;transform:translateY(-50%);font-size:12px;color:var(--w-text-3)}.gridline{position:absolute;left:0;right:0;height:1px;background:var(--w-line)}.median-line{position:absolute;width:100%;height:100%;overflow:visible;pointer-events:none}.median-line line{stroke:#A0A4B0;stroke-width:1.5;vector-effect:non-scaling-stroke}.point{position:absolute;width:10px;height:10px;margin:-5px 0 0 -5px;background:#7855FE;border:1px solid white;border-radius:50%;box-shadow:0 0 0 1px #7855FE;z-index:1}.point.muted{background:#A0A4B0;box-shadow:0 0 0 1px #A0A4B0}.point:hover,.point:focus-visible{outline:2px solid #5F1FE6;outline-offset:3px;z-index:2}.x-labels{position:absolute;top:100%;left:0;right:0;height:20px}.x-labels span{position:absolute;transform:translateX(-50%);font-size:12px;color:var(--w-text-3);padding-top:6px}.x-name{text-align:center;margin:14px 0 0 42px;font-size:12px;color:var(--w-text-2)}.heat-scroll{overflow-x:auto;padding-top:4px}.heat{display:grid;grid-template-columns:70px minmax(0,1fr);gap:6px 8px;align-items:center}.heat-dates{height:18px;position:relative}.heat-dates span{position:absolute;transform:translateX(-50%);font-size:12px;color:var(--w-text-3);white-space:nowrap}.person{font-size:12px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cells{display:grid;gap:2px}.cells>button{display:block;height:22px;border:0;padding:0;border-radius:2px;cursor:pointer}.cells>button:focus-visible{outline:2px solid var(--w-pri);outline-offset:1px}.heat-legend{display:flex;gap:12px;flex-wrap:wrap;color:var(--w-text-3);font-size:12px}.heat-legend>span{display:flex;align-items:center;gap:4px}.heat-legend i{width:10px;height:10px;border-radius:2px}.empty{color:var(--w-text-3);text-align:center;font-size:13px;padding:32px 0}.task-table{overflow:auto;max-height:300px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px;border-bottom:1px solid var(--w-line)}th{font-size:12px;font-weight:500;color:var(--w-text-3)}@media(max-width:1100px){.operator-charts{grid-template-columns:1fr}}@media(max-width:600px){.operator-charts{margin:12px}section{padding:16px}}
</style>
